-- 기존 데이터베이스 삭제 및 재생성
DROP DATABASE IF EXISTS `if0_39723369_min`;
CREATE DATABASE IF NOT EXISTS `if0_39723369_min` DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `if0_39723369_min`;

-- 외래키 체크 비활성화 (빠른 삽입)
SET FOREIGN_KEY_CHECKS = 0;
SET AUTOCOMMIT = 0;
START TRANSACTION;

-- 테이블 구조: brands
DROP TABLE IF EXISTS `brands`;
CREATE TABLE `brands` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `name_ko` varchar(100) NOT NULL,
  `name_en` varchar(100) DEFAULT NULL,
  `logo_url` varchar(255) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `name_ko` (`name_ko`)
) ENGINE=InnoDB AUTO_INCREMENT=13 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- 테이블 구조: categories
DROP TABLE IF EXISTS `categories`;
CREATE TABLE `categories` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(100) NOT NULL,
  `parent_id` int(11) unsigned DEFAULT NULL,
  `default_margin_rate` decimal(5,4) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `name` (`name`),
  KEY `parent_id` (`parent_id`),
  CONSTRAINT `categories_ibfk_1` FOREIGN KEY (`parent_id`) REFERENCES `categories` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=15 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- 테이블 구조: delivery_addresses
DROP TABLE IF EXISTS `delivery_addresses`;
CREATE TABLE `delivery_addresses` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL,
  `address_name` varchar(100) NOT NULL COMMENT '주소 별칭',
  `house_number` varchar(50) DEFAULT NULL COMMENT '집 번호',
  `street` varchar(200) NOT NULL COMMENT '거리명',
  `barangay` varchar(100) NOT NULL COMMENT '바랑가이',
  `city` varchar(100) NOT NULL COMMENT '시/도시',
  `province` varchar(100) NOT NULL COMMENT '주/지방',
  `postal_code` varchar(20) DEFAULT NULL COMMENT '우편번호',
  `detailed_address` text DEFAULT NULL COMMENT '상세 주소',
  `landmark` varchar(200) DEFAULT NULL COMMENT '랜드마크',
  `delivery_notes` text DEFAULT NULL COMMENT '배달 메모',
  `latitude` decimal(10,8) DEFAULT NULL COMMENT '위도',
  `longitude` decimal(11,8) DEFAULT NULL COMMENT '경도',
  `is_default` tinyint(1) DEFAULT 0 COMMENT '기본 주소 여부',
  `is_active` tinyint(1) DEFAULT 1 COMMENT '활성 상태',
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_delivery_addresses_user_id` (`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 테이블 구조: delivery_order_items
DROP TABLE IF EXISTS `delivery_order_items`;
CREATE TABLE `delivery_order_items` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_id` int(11) NOT NULL,
  `product_id` int(11) NOT NULL,
  `product_name` varchar(255) NOT NULL COMMENT '상품명',
  `product_price` decimal(10,2) NOT NULL COMMENT '단가',
  `quantity` int(11) NOT NULL COMMENT '수량',
  `subtotal` decimal(10,2) NOT NULL COMMENT '소계',
  `product_options` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '상품 옵션' CHECK (json_valid(`product_options`)),
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_delivery_order_items_order_id` (`order_id`),
  KEY `idx_delivery_order_items_product_id` (`product_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 테이블 구조: delivery_orders
DROP TABLE IF EXISTS `delivery_orders`;
CREATE TABLE `delivery_orders` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_number` varchar(50) NOT NULL COMMENT '주문 번호',
  `user_id` int(11) NOT NULL,
  `store_id` int(11) NOT NULL COMMENT '주문한 점포',
  `delivery_address_id` int(11) NOT NULL,
  `delivery_zone_id` int(11) DEFAULT NULL,
  `subtotal` decimal(10,2) NOT NULL COMMENT '상품 총액',
  `delivery_fee` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '배달비',
  `discount_amount` decimal(10,2) DEFAULT 0.00 COMMENT '할인 금액',
  `total_amount` decimal(10,2) NOT NULL COMMENT '총 결제 금액',
  `payment_method` enum('cod','gcash','paymaya','online') DEFAULT 'cod' COMMENT '결제 방법',
  `payment_status` enum('pending','paid','failed','refunded') DEFAULT 'pending' COMMENT '결제 상태',
  `cod_amount` decimal(10,2) DEFAULT NULL COMMENT 'COD 결제 금액',
  `change_amount` decimal(10,2) DEFAULT NULL COMMENT '거스름돈',
  `order_status` enum('pending','confirmed','preparing','ready_for_delivery','out_for_delivery','delivered','cancelled') DEFAULT 'pending' COMMENT '주문 상태',
  `delivery_date` date DEFAULT NULL COMMENT '배달 예정일',
  `delivery_time_slot` varchar(20) DEFAULT NULL COMMENT '배달 시간대',
  `estimated_delivery_time` timestamp NULL DEFAULT NULL COMMENT '예상 배달 시간',
  `actual_delivery_time` timestamp NULL DEFAULT NULL COMMENT '실제 배달 시간',
  `special_instructions` text DEFAULT NULL COMMENT '특별 요청사항',
  `delivery_notes` text DEFAULT NULL COMMENT '배달 메모',
  `cancellation_reason` text DEFAULT NULL COMMENT '취소 사유',
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `order_number` (`order_number`),
  KEY `idx_delivery_orders_user_id` (`user_id`),
  KEY `idx_delivery_orders_store_id` (`store_id`),
  KEY `idx_delivery_orders_status` (`order_status`),
  KEY `idx_delivery_orders_number` (`order_number`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 테이블 구조: delivery_settings
DROP TABLE IF EXISTS `delivery_settings`;
CREATE TABLE `delivery_settings` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `setting_key` varchar(100) NOT NULL,
  `setting_value` text NOT NULL,
  `setting_type` enum('string','number','boolean','json') DEFAULT 'string',
  `description` text DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `setting_key` (`setting_key`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 테이블 구조: delivery_tracking
DROP TABLE IF EXISTS `delivery_tracking`;
CREATE TABLE `delivery_tracking` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_id` int(11) NOT NULL,
  `status` enum('order_placed','order_confirmed','preparing','ready_for_pickup','picked_up','out_for_delivery','delivered','failed_delivery','cancelled') NOT NULL,
  `status_message` varchar(255) DEFAULT NULL COMMENT '상태 메시지',
  `latitude` decimal(10,8) DEFAULT NULL COMMENT '현재 위도',
  `longitude` decimal(11,8) DEFAULT NULL COMMENT '현재 경도',
  `updated_by_user_id` int(11) DEFAULT NULL COMMENT '상태 업데이트한 사용자',
  `notes` text DEFAULT NULL COMMENT '추가 메모',
  `timestamp` timestamp NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_delivery_tracking_order_id` (`order_id`),
  KEY `idx_delivery_tracking_timestamp` (`timestamp`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 테이블 구조: delivery_zones
DROP TABLE IF EXISTS `delivery_zones`;
CREATE TABLE `delivery_zones` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `zone_name` varchar(100) NOT NULL COMMENT '배달 지역명',
  `barangay` varchar(100) DEFAULT NULL COMMENT '바랑가이',
  `city` varchar(100) NOT NULL COMMENT '시/도시',
  `province` varchar(100) NOT NULL COMMENT '주/지방',
  `delivery_fee` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '기본 배달비',
  `min_order_amount` decimal(10,2) DEFAULT 0.00 COMMENT '최소 주문 금액',
  `free_delivery_threshold` decimal(10,2) DEFAULT NULL COMMENT '무료 배달 최소 금액',
  `estimated_delivery_time` int(11) DEFAULT 60 COMMENT '예상 배달 시간(분)',
  `max_delivery_time` int(11) DEFAULT 120 COMMENT '최대 배달 시간(분)',
  `service_start_time` time DEFAULT '08:00:00' COMMENT '서비스 시작 시간',
  `service_end_time` time DEFAULT '22:00:00' COMMENT '서비스 종료 시간',
  `is_active` tinyint(1) DEFAULT 1 COMMENT '서비스 가능 여부',
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 테이블 구조: inventory
DROP TABLE IF EXISTS `inventory`;
CREATE TABLE `inventory` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `product_id` int(11) unsigned NOT NULL,
  `store_id` int(11) unsigned NOT NULL,
  `quantity` int(11) NOT NULL DEFAULT 0,
  `selling_price` decimal(10,2) DEFAULT NULL,
  `cost_price` decimal(10,2) DEFAULT NULL,
  `low_stock_threshold` int(11) NOT NULL DEFAULT 10,
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `box_price` decimal(10,2) DEFAULT NULL COMMENT '점포별 박스단가',
  PRIMARY KEY (`id`),
  UNIQUE KEY `product_store_unique` (`product_id`,`store_id`),
  KEY `store_id` (`store_id`),
  CONSTRAINT `inventory_ibfk_1` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON DELETE CASCADE,
  CONSTRAINT `inventory_ibfk_2` FOREIGN KEY (`store_id`) REFERENCES `stores` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=132713 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- 테이블 구조: inventory_transactions
DROP TABLE IF EXISTS `inventory_transactions`;
CREATE TABLE `inventory_transactions` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `inventory_id` int(11) unsigned NOT NULL,
  `user_id` int(11) unsigned DEFAULT NULL,
  `transaction_type` enum('입고','판매','반품','재고조정','최초등록') NOT NULL,
  `quantity_change` int(11) NOT NULL,
  `remarks` text DEFAULT NULL,
  `transaction_date` timestamp NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `inventory_id` (`inventory_id`),
  KEY `user_id` (`user_id`),
  CONSTRAINT `inventory_transactions_ibfk_1` FOREIGN KEY (`inventory_id`) REFERENCES `inventory` (`id`) ON DELETE CASCADE,
  CONSTRAINT `inventory_transactions_ibfk_2` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=325 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- 테이블 구조: margin_rules
DROP TABLE IF EXISTS `margin_rules`;
CREATE TABLE `margin_rules` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `category_id` int(11) unsigned NOT NULL,
  `margin_percentage` decimal(5,2) NOT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `category_id_unique` (`category_id`),
  CONSTRAINT `margin_rules_ibfk_1` FOREIGN KEY (`category_id`) REFERENCES `categories` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- 테이블 구조: price_change_history
DROP TABLE IF EXISTS `price_change_history`;
CREATE TABLE `price_change_history` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `product_id` int(11) NOT NULL,
  `store_id` int(11) DEFAULT NULL,
  `old_cost_price` decimal(10,2) DEFAULT NULL,
  `new_cost_price` decimal(10,2) DEFAULT NULL,
  `old_selling_price` decimal(10,2) DEFAULT NULL,
  `new_selling_price` decimal(10,2) DEFAULT NULL,
  `old_margin_rate` decimal(5,2) DEFAULT NULL,
  `new_margin_rate` decimal(5,2) DEFAULT NULL,
  `change_type` enum('cost_only','selling_only','both','margin_adjust') NOT NULL DEFAULT 'both',
  `change_reason` varchar(255) DEFAULT NULL,
  `purchase_id` varchar(50) DEFAULT NULL COMMENT '매입이력에서 변경된 경우 매입ID',
  `changed_by_user_id` int(11) NOT NULL,
  `changed_at` timestamp NULL DEFAULT current_timestamp(),
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_product_id` (`product_id`),
  KEY `idx_store_id` (`store_id`),
  KEY `idx_changed_at` (`changed_at`),
  KEY `idx_changed_by_user_id` (`changed_by_user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=134 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='상품 가격변경 이력';

-- 테이블 구조: products
DROP TABLE IF EXISTS `products`;
CREATE TABLE `products` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `sku` varchar(100) NOT NULL,
  `name_ko` varchar(255) NOT NULL,
  `name_en` varchar(255) DEFAULT NULL,
  `description` text DEFAULT NULL,
  `category_id` int(11) unsigned DEFAULT NULL,
  `brand_id` int(11) unsigned DEFAULT NULL,
  `cost_price` decimal(10,2) NOT NULL DEFAULT 0.00,
  `margin_rate` decimal(5,4) DEFAULT NULL,
  `selling_price` decimal(10,2) NOT NULL DEFAULT 0.00,
  `wholesale_price` decimal(10,2) DEFAULT NULL,
  `event_price` decimal(10,2) DEFAULT NULL,
  `event_start_date` datetime DEFAULT NULL,
  `event_end_date` datetime DEFAULT NULL,
  `image_url` varchar(255) DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `last_modified_by_user_id` int(11) unsigned DEFAULT NULL,
  `pieces_per_box` int(11) DEFAULT 1,
  `barcode` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `category_id` (`category_id`),
  KEY `brand_id` (`brand_id`),
  KEY `last_modified_by_user_id` (`last_modified_by_user_id`),
  CONSTRAINT `products_ibfk_1` FOREIGN KEY (`category_id`) REFERENCES `categories` (`id`) ON DELETE SET NULL,
  CONSTRAINT `products_ibfk_2` FOREIGN KEY (`brand_id`) REFERENCES `brands` (`id`) ON DELETE SET NULL,
  CONSTRAINT `products_ibfk_3` FOREIGN KEY (`last_modified_by_user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=23196 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 테이블 구조: purchase_items
DROP TABLE IF EXISTS `purchase_items`;
CREATE TABLE `purchase_items` (
  `item_id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `purchase_id` int(10) unsigned NOT NULL,
  `product_id` int(11) unsigned NOT NULL,
  `purchase_type` enum('box','piece') NOT NULL DEFAULT 'box',
  `quantity` int(11) NOT NULL,
  `unit_price` decimal(10,2) NOT NULL,
  `discount_rate` decimal(5,2) DEFAULT 0.00 COMMENT '할인율 (%)',
  `discounted_total` decimal(10,2) DEFAULT NULL COMMENT '할인후 총액',
  PRIMARY KEY (`item_id`),
  KEY `purchase_id` (`purchase_id`),
  KEY `product_id` (`product_id`),
  CONSTRAINT `purchase_items_ibfk_1` FOREIGN KEY (`purchase_id`) REFERENCES `purchases` (`purchase_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `purchase_items_ibfk_2` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=331 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- 테이블 구조: purchases
DROP TABLE IF EXISTS `purchases`;
CREATE TABLE `purchases` (
  `purchase_id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `supplier_id` int(11) unsigned NOT NULL,
  `purchase_date` date NOT NULL,
  `total_amount` decimal(10,2) NOT NULL,
  `total_items` int(11) NOT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `deleted_at` timestamp NULL DEFAULT NULL,
  `deleted_by_user_id` int(11) DEFAULT NULL,
  PRIMARY KEY (`purchase_id`),
  KEY `supplier_id` (`supplier_id`),
  CONSTRAINT `purchases_ibfk_1` FOREIGN KEY (`supplier_id`) REFERENCES `suppliers` (`id`) ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=43 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- 테이블 구조: settings
DROP TABLE IF EXISTS `settings`;
CREATE TABLE `settings` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `setting_key` varchar(255) NOT NULL,
  `setting_value` text NOT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `setting_key` (`setting_key`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 테이블 구조: shopping_cart
DROP TABLE IF EXISTS `shopping_cart`;
CREATE TABLE `shopping_cart` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL,
  `product_id` int(11) NOT NULL,
  `store_id` int(11) NOT NULL COMMENT '상품을 구매할 점포',
  `quantity` int(11) NOT NULL DEFAULT 1,
  `added_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_cart_user_product_store` (`user_id`,`product_id`,`store_id`),
  KEY `idx_shopping_cart_user_id` (`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 테이블 구조: store_transfer_items
DROP TABLE IF EXISTS `store_transfer_items`;
CREATE TABLE `store_transfer_items` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `transfer_id` int(11) NOT NULL COMMENT '이동 ID',
  `product_id` int(11) NOT NULL COMMENT '상품 ID',
  `quantity` int(11) NOT NULL COMMENT '이동 수량',
  `unit_cost_price` decimal(10,2) NOT NULL COMMENT '단위 원가',
  `total_price` decimal(12,2) NOT NULL COMMENT '총 원가',
  `remarks` varchar(255) DEFAULT NULL COMMENT '비고',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_transfer_id` (`transfer_id`),
  KEY `idx_product_id` (`product_id`)
) ENGINE=InnoDB AUTO_INCREMENT=18 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='점간이동 상세 항목';

-- 테이블 구조: store_transfers
DROP TABLE IF EXISTS `store_transfers`;
CREATE TABLE `store_transfers` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `from_store_id` int(11) NOT NULL COMMENT '출발 점포 ID',
  `to_store_id` int(11) NOT NULL COMMENT '목적지 점포 ID',
  `user_id` int(11) NOT NULL COMMENT '이동 요청자 ID',
  `transfer_date` date NOT NULL COMMENT '이동 날짜',
  `total_amount` decimal(12,2) NOT NULL DEFAULT 0.00 COMMENT '총 이동 금액 (원가 기준)',
  `final_amount` decimal(12,2) NOT NULL DEFAULT 0.00 COMMENT '최종 금액',
  `status` enum('draft','confirmed','cancelled') NOT NULL DEFAULT 'draft' COMMENT '상태',
  `notes` text DEFAULT NULL COMMENT '비고',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_from_store_id` (`from_store_id`),
  KEY `idx_to_store_id` (`to_store_id`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_transfer_date` (`transfer_date`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='점간이동 마스터';

-- 테이블 구조: stores
DROP TABLE IF EXISTS `stores`;
CREATE TABLE `stores` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(100) NOT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `name` (`name`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- 테이블 구조: suppliers
DROP TABLE IF EXISTS `suppliers`;
CREATE TABLE `suppliers` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(100) NOT NULL,
  `contact_person` varchar(100) DEFAULT NULL,
  `phone` varchar(20) DEFAULT NULL,
  `email` varchar(100) DEFAULT NULL,
  `address` varchar(255) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `memo` text DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=26 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- 테이블 구조: users
DROP TABLE IF EXISTS `users`;
CREATE TABLE `users` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `username` varchar(50) NOT NULL,
  `password` varchar(255) NOT NULL,
  `full_name` varchar(100) NOT NULL,
  `email` varchar(100) DEFAULT NULL,
  `phone` varchar(20) DEFAULT NULL,
  `role` enum('user','admin','super_admin') NOT NULL DEFAULT 'user',
  `store_id` int(11) unsigned DEFAULT NULL,
  `remember_token` varchar(255) DEFAULT NULL,
  `remember_token_expiry` datetime DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `google_id` varchar(255) DEFAULT NULL COMMENT '구글 계정 고유 ID',
  `auth_provider` enum('email','google') DEFAULT 'email' COMMENT '인증 제공자',
  `profile_image_url` text DEFAULT NULL COMMENT '프로필 이미지 URL',
  `default_delivery_address_id` int(11) DEFAULT NULL COMMENT '기본 배달 주소 ID',
  `preferred_language` enum('en','ko') DEFAULT 'en' COMMENT '선호 언어',
  `phone_verified` tinyint(1) DEFAULT 0 COMMENT '전화번호 인증 여부',
  `is_delivery_available` tinyint(1) DEFAULT 1 COMMENT '배달 서비스 이용 가능 여부',
  PRIMARY KEY (`id`),
  UNIQUE KEY `username` (`username`),
  UNIQUE KEY `email` (`email`),
  UNIQUE KEY `google_id` (`google_id`),
  KEY `fk_user_store` (`store_id`),
  CONSTRAINT `fk_user_store` FOREIGN KEY (`store_id`) REFERENCES `stores` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- 테이블 구조: wholesale_customers
DROP TABLE IF EXISTS `wholesale_customers`;
CREATE TABLE `wholesale_customers` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL COMMENT '거래처명',
  `phone` varchar(50) DEFAULT NULL COMMENT '전화번호',
  `address` text DEFAULT NULL COMMENT '주소',
  `memo` text DEFAULT NULL COMMENT '기타 메모',
  `is_active` tinyint(1) NOT NULL DEFAULT 1 COMMENT '활성 상태',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_name` (`name`),
  KEY `idx_phone` (`phone`),
  KEY `idx_active` (`is_active`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='도매 거래처 정보';

-- 테이블 구조: wholesale_products
DROP TABLE IF EXISTS `wholesale_products`;
CREATE TABLE `wholesale_products` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `product_id` int(11) NOT NULL COMMENT '상품 ID',
  `wholesale_name_ko` varchar(255) DEFAULT NULL,
  `wholesale_name_en` varchar(255) DEFAULT NULL,
  `wholesale_skus` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`wholesale_skus`)),
  `wholesale_description` text DEFAULT NULL,
  `store_id` int(11) NOT NULL COMMENT '점포 ID',
  `wholesale_price` decimal(10,2) NOT NULL COMMENT '도매가',
  `min_quantity` int(11) DEFAULT 1 COMMENT '최소 주문 수량',
  `is_active` tinyint(1) NOT NULL DEFAULT 1 COMMENT '활성 상태',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_product_store` (`product_id`,`store_id`),
  KEY `idx_product_id` (`product_id`),
  KEY `idx_store_id` (`store_id`),
  KEY `idx_active` (`is_active`)
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='도매 상품 가격 정보';

-- 테이블 구조: wholesale_sale_items
DROP TABLE IF EXISTS `wholesale_sale_items`;
CREATE TABLE `wholesale_sale_items` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `sale_id` int(11) NOT NULL COMMENT '판매 ID',
  `product_id` int(11) NOT NULL COMMENT '상품 ID',
  `quantity` int(11) NOT NULL COMMENT '수량',
  `unit_price` decimal(10,2) NOT NULL COMMENT '단가',
  `total_price` decimal(12,2) NOT NULL COMMENT '총가격',
  `remarks` varchar(200) DEFAULT NULL COMMENT '상품별 비고 (배송지시, 포장요청 등)',
  `notes` varchar(255) DEFAULT NULL COMMENT '비고',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_sale_id` (`sale_id`),
  KEY `idx_product_id` (`product_id`)
) ENGINE=InnoDB AUTO_INCREMENT=26 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='도매 판매 항목';

-- 테이블 구조: wholesale_sales
DROP TABLE IF EXISTS `wholesale_sales`;
CREATE TABLE `wholesale_sales` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `customer_id` int(11) NOT NULL COMMENT '거래처 ID',
  `store_id` int(11) NOT NULL COMMENT '점포 ID',
  `user_id` int(11) NOT NULL COMMENT '판매자 ID',
  `sale_date` date NOT NULL COMMENT '판매 날짜',
  `total_amount` decimal(12,2) NOT NULL DEFAULT 0.00 COMMENT '총 판매 금액',
  `tax_amount` decimal(12,2) DEFAULT 0.00 COMMENT '세금 금액',
  `discount_amount` decimal(12,2) DEFAULT 0.00 COMMENT '할인 금액',
  `final_amount` decimal(12,2) NOT NULL DEFAULT 0.00 COMMENT '최종 금액',
  `status` enum('draft','confirmed','cancelled') NOT NULL DEFAULT 'draft' COMMENT '상태',
  `notes` text DEFAULT NULL COMMENT '비고',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_customer_id` (`customer_id`),
  KEY `idx_store_id` (`store_id`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_sale_date` (`sale_date`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='도매 판매 내역';

-- 테이블 구조: wishlists
DROP TABLE IF EXISTS `wishlists`;
CREATE TABLE `wishlists` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL,
  `product_id` int(11) NOT NULL,
  `added_at` timestamp NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_wishlist_user_product` (`user_id`,`product_id`),
  KEY `idx_wishlists_user_id` (`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

